public indirect enum MamachiJSONValue: Codable, Equatable, Sendable {
    case null
    case bool(Bool)
    case integer(Int64)
    case number(Double)
    case string(String)
    case array([MamachiJSONValue])
    case object([String: MamachiJSONValue])

    public init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if container.decodeNil() { self = .null }
        else if let value = try? container.decode(Bool.self) { self = .bool(value) }
        else if let value = try? container.decode(Int64.self) { self = .integer(value) }
        else if let value = try? container.decode(Double.self) { self = .number(value) }
        else if let value = try? container.decode(String.self) { self = .string(value) }
        else if let value = try? container.decode([MamachiJSONValue].self) { self = .array(value) }
        else if let value = try? container.decode([String: MamachiJSONValue].self) { self = .object(value) }
        else { throw DecodingError.dataCorruptedError(in: container, debugDescription: "Unsupported JSON value") }
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case .null: try container.encodeNil()
        case .bool(let value): try container.encode(value)
        case .integer(let value): try container.encode(value)
        case .number(let value): try container.encode(value)
        case .string(let value): try container.encode(value)
        case .array(let value): try container.encode(value)
        case .object(let value): try container.encode(value)
        }
    }
}

public struct MamachiCommandEnvelope: Codable, Equatable, Sendable {
    public let id: String
    public let type: MamachiCommandType
    public let actor: String
    public let expectedRevision: Int?
    public let payload: MamachiJSONValue

    public init(id: String, type: MamachiCommandType, actor: String, expectedRevision: Int?, payload: MamachiJSONValue) {
        self.id = id
        self.type = type
        self.actor = actor
        self.expectedRevision = expectedRevision
        self.payload = payload
    }
}

